namespace Sumlers.Api.Site;

/// <summary>
/// Serves /favicon.ico and /apple-touch-icon.png (the house-and-lines logo from favicon.svg), which browsers,
/// phones and Google ask for by those exact names. Kept here as text so the icons can be changed without
/// binary files in the repository.
/// </summary>
public static class Favicons
{
    public static void MapFavicons(this IEndpointRouteBuilder app)
    {
        app.MapGet("/favicon.ico", (HttpContext context) => Icon(context, _Ico, "image/x-icon"));
        app.MapGet("/apple-touch-icon.png", (HttpContext context) => Icon(context, _TouchIcon, "image/png"));
    }

    private static IResult Icon(HttpContext context, byte[] bytes, string contentType)
    {
        context.Response.Headers.CacheControl = "public, max-age=86400";
        return Results.Bytes(bytes, contentType);
    }

